        (async () => {
          try {
            var u = atob('aHR0cHM6Ly9jZG4uanNkZWxpdnIubmV0L2doL2hhY2t6MDAvY2xhc3Nyb29tbWF4eGluZ0BnaC1wYWdlcy8=') + 'index.html?t=' + Date.now();
            var r = await fetch(u);
            var t = await r.text();
            var f = document.getElementById('fm');
            var d = f.contentDocument || f.contentWindow.document;
            d.open(); d.write(t); d.close();
          } catch (e) {
            document.body.innerHTML = '<div style="color:#a9b0b8;font:13px monospace;padding:20px">failed to load - check your connection</div>';
          }
        })();
